ProbabilityTheory.indepFun_iff_map_prod_eq_prod_map_map.{u_1, u_6, u_7} {Ω : Type u_1} {β : Type u_6} {β' : Type u_7}
  {_mΩ : MeasurableSpace Ω} {μ : MeasureTheory.Measure Ω} {f : Ω → β} {g : Ω → β'} {mβ : MeasurableSpace β}
  {mβ' : MeasurableSpace β'} [MeasureTheory.IsFiniteMeasure μ] (hf : AEMeasurable f μ) (hg : AEMeasurable g μ) :
  ProbabilityTheory.IndepFun f g μ ↔
